def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    closest_vowel = ''

    for i in range(len(word) - 2):
        if word[i] in vowels and word[i+1] not in vowels and word[i+2] in vowels:
            closest_vowel = word[i+1]
            break

    return closest_vowel
