def find_max(words):
    def unique_chars_count(word):
        return len(set(word))

    max_unique = 0
    result_word = ""
    for word in words:
        if unique_chars_count(word) > max_unique or (unique_chars_count(word) == max_unique and word < result_word):
            max_unique = unique_chars_count(word)
            result_word = word
    return result_word
